                .set_response_header(SEC_WEBSOCKET_ACCEPT, &accept_key)
                .await
                .set_response_body(&vec![])
                .await
                .try_send()
                .await;
            if send_result.is_err() {
                ctx.aborted().await.closed().await;
            }
        }
